398→        use std::sync::{Arc, Mutex};
399→
400→        let lines = Arc::new(Mutex::new(Vec::new()));
401→        let lines_clone = Arc::clone(&lines);
402→
403→        let callback: OutputCallback = Box::new(move |line| {
404→            lines_clone.lock().unwrap().push(line);
405→        });
406→
407→        let options = CommandOptions::default();
