418→        use std::sync::{Arc, Mutex};
419→
420→        let lines = Arc::new(Mutex::new(Vec::new()));
421→        let lines_clone = Arc::clone(&lines);
422→
423→        let callback: OutputCallback = Box::new(move |line| {
