448→    fn shell_flag_uses_non_interactive_in_ci() {
449→        // When CI env var is set, shell_flag should use -lc (non-interactive)
450→        // to avoid "cannot set terminal process group" errors
451→        std::env::set_var("CI", "true");
452→        let flag = shell_flag("/bin/bash");
453→        std::env::remove_var("CI");
454→        assert_eq!(flag, "-lc");
455→    }
