457→    #[test]
458→    fn shell_flag_uses_interactive_outside_ci() {
459→        // Ensure no CI env vars are set for this test
460→        let ci_vars = ["CI", "GITHUB_ACTIONS", "GITLAB_CI", "CIRCLECI", "TRAVIS"];
461→        let saved: Vec<_> = ci_vars
462→            .iter()
463→            .map(|k| (*k, std::env::var(k).ok()))
464→            .collect();
465→        for k in &ci_vars {
466→            std::env::remove_var(k);
467→        }
468→
469→        let flag = shell_flag("/bin/bash");
470→
471→        // Restore env vars
472→        for (k, v) in &saved {
473→            if let Some(val) = v {
474→                std::env::set_var(k, val);
475→            }
476→        }
477→        assert_eq!(flag, "-lic");
478→    }
479→}
