    let mut cmd = Command::new(cargo_bin("bivvy"));
    cmd.current_dir(temp.path());
    cmd.args(["run", "--env", "ci"]);
    cmd.assert()
        .success()
        .stdout(predicate::str::contains("always"))
        .stdout(predicate::str::contains("ci_only"));
    Ok(())
}

